class LibraryMember {private static int count=0;private final String memberNumber;private int limit,borrowed;public LibraryMember(int l){if(l<=0)throw new IllegalArgumentException("Limit must be positive");limit=l;memberNumber="LIB-"+(100+ ++count);}public String getMemberNumber(){return memberNumber;}public void borrowBook(){if(borrowed>=limit)throw new IllegalStateException("Limit reached");borrowed++;}public void borrowBook(String genre){System.out.println("Genre: "+genre);borrowBook();}public int getBooksBorrowed(){return borrowed;}public static int getMembersEnrolled(){return count;}}
class FacultyMember extends LibraryMember {private String department;public FacultyMember(int l,String d){super(l);department=d;}}
public class LibraryMembershipAuditMain {public static boolean isValidRenewalCode(String s){return s!=null&&s.length()==4&&s.charAt(0)=='R'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}public static String processNightlyAudit(LibraryMember[] ms){int done=0,nulls=0,faculty=0,regular=0;for(LibraryMember m:ms){if(m==null){nulls++;continue;}done++;if(m instanceof FacultyMember)faculty++;else regular++;}return done+" processed | "+nulls+" null skipped | "+faculty+" faculty | "+regular+" regular";}public static void main(String[] a){LibraryMember m=new LibraryMember(3);System.out.println(m.getMemberNumber());System.out.println(LibraryMember.getMembersEnrolled());System.out.println(isValidRenewalCode("R12A"));m.borrowBook();m.borrowBook("Fiction");System.out.println(m.getBooksBorrowed());System.out.println(processNightlyAudit(new LibraryMember[]{new FacultyMember(5,"Physics"),null,new LibraryMember(3)}));}}
